import heapq

class Solution:
    def minInterval(self, intervals: list[list[int]], queries: list[int]) -> list[int]:
        intervals.sort()
        sorted_queries = sorted([(q, i) for i, q in enumerate(queries)])

        pq = []
        ans = [-1] * len(queries)
        idx = 0
        n = len(intervals)

        for q, orig_idx in sorted_queries:
            while idx < n and intervals[idx][0] <= q:
                l, r = intervals[idx]
                heapq.heappush(pq, (r - l + 1, r))
                idx += 1

            while pq and pq[0][1] < q:
                heapq.heappop(pq)

            if pq:
                ans[orig_idx] = pq[0][0]

        return ans

class Solution {
public:
    vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {
        sort(intervals.begin(), intervals.end());
        int q = queries.size();
        vector<pair<int, int>> sq(q);
        for (int i = 0; i < q; ++i) sq[i] = {queries[i], i};
        sort(sq.begin(), sq.end());

        using P = pair<int, int>;
        priority_queue<P, vector<P>, greater<P>> pq;
        vector<int> ans(q, -1);
        int idx = 0, n = intervals.size();

        for (const auto& [queryVal, origIdx] : sq) {
            while (idx < n && intervals[idx][0] <= queryVal) {
                int l = intervals[idx][0], r = intervals[idx][1];
                pq.push({r - l + 1, r});
                idx++;
            }
            while (!pq.empty() && pq.top().second < queryVal) {
                pq.pop();
            }
            if (!pq.empty()) {
                ans[origIdx] = pq.top().first;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] minInterval(int[][] intervals, int[] queries) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        int q = queries.length;
        int[][] sq = new int[q][2];
        for (int i = 0; i < q; ++i) sq[i] = new int[]{queries[i], i};
        Arrays.sort(sq, (a, b) -> Integer.compare(a[0], b[0]));

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        int[] ans = new int[q];
        Arrays.fill(ans, -1);
        int idx = 0, n = intervals.length;

        for (int[] query : sq) {
            int queryVal = query[0], origIdx = query[1];
            while (idx < n && intervals[idx][0] <= queryVal) {
                int l = intervals[idx][0], r = intervals[idx][1];
                pq.offer(new int[]{r - l + 1, r});
                idx++;
            }
            while (!pq.isEmpty() && pq.peek()[1] < queryVal) {
                pq.poll();
            }
            if (!pq.isEmpty()) {
                ans[origIdx] = pq.peek()[0];
            }
        }
        return ans;
    }
}

/**
 * @param {number[][]} intervals
 * @param {number[]} queries
 * @return {number[]}
 */
var minInterval = function(intervals, queries) {
    intervals.sort((a, b) => a[0] - b[0]);
    const q = queries.length;
    const sq = queries.map((val, i) => [val, i]);
    sq.sort((a, b) => a[0] - b[0]);

    const pq = [];
    const push = (item) => {
        pq.push(item);
        let idx = pq.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (pq[p][0] > pq[idx][0]) {
                [pq[p], pq[idx]] = [pq[idx], pq[p]];
                idx = p;
            } else break;
        }
    };

    const pop = () => {
        if (pq.length === 0) return null;
        const top = pq[0];
        const last = pq.pop();
        if (pq.length > 0) {
            pq[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, smallest = idx;
                if (left < pq.length && pq[left][0] < pq[smallest][0]) smallest = left;
                if (right < pq.length && pq[right][0] < pq[smallest][0]) smallest = right;
                if (smallest !== idx) {
                    [pq[idx], pq[smallest]] = [pq[smallest], pq[idx]];
                    idx = smallest;
                } else break;
            }
        }
        return top;
    };

    const ans = Array(q).fill(-1);
    let idx = 0, n = intervals.length;

    for (const [queryVal, origIdx] of sq) {
        while (idx < n && intervals[idx][0] <= queryVal) {
            const [l, r] = intervals[idx];
            push([r - l + 1, r]);
            idx++;
        }
        while (pq.length > 0 && pq[0][1] < queryVal) {
            pop();
        }
        if (pq.length > 0) {
            ans[origIdx] = pq[0][0];
        }
    }
    return ans;
};
